content.content:
1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	// Namespace imports throughout, and every constant read through a `typeof`
3	// guard: the engine lane and the pack lane converge on separate cycles, so this
4	// file spends windows beside an engine that predates one of the symbols below.
5	// A named import of an absent export is a link-time error that faults the whole
6	// pack; a guarded read simply drops that one advisory, which is the behaviour
7	// the older engine already has.
8	import * as settingsNames from '../../../engine/settings-file-names.mjs';
9	import * as repoContext from '../../../engine/checks/helpers/repo-context.mjs';
10	import * as installedVersions from '../../../engine/installed-versions.mjs';
11	import * as renamedPacks from '../../../engine/pack_loader/renamed-packs.mjs';
12	import * as packRegistry from '../../../engine/pack_loader/pack-registry.mjs';
13	import * as versionSpec from '../../../engine/version.mjs';
14	import * as servedBy from '../../../engine/served-by.mjs';
15	
16	// THE ADVISORY HALF OF EVERY DECLARATION-SHAPE TOLERANCE the engine still
17	// carries. Each of those tolerances lets a member's own file be read in a shape
18	// that has since been renamed, and each is removed a week after this advisory ships
19	// (#1638) — the window a repo converging nightly needs to act on its own finding.
20	// Nothing was telling the repos, which is why the window needed the advisory first.
21	//
22	// A tolerance with no advisory asks people to migrate off something they have no
23	// way of knowing they are on, so this rule fires in the repo that HOLDS the old
24	// shape rather than in the canon that tolerates it (basics' *Adding a legacy
25	// tolerance*). It reads the member's own declaration and stamp and names, per
26	// finding, the edit that moves it forward.
27	//
28	// ADVISORY, permanently. The old shape works — that is what a tolerance means —
29	// so a blocking finding would stop a member's build over something that is not
30	// broken. What the advisory buys is that the removal's gate can eventually read
31	// zero, which is the only way the tolerance ever comes out.
32	const rule = {
33	  id: 'legacy-shape-in-use',
34	  severity: 'advisory',
35	  since: '2026-09-03',
36	  description: 'This repo\'s Claudinite declaration and stamp use no shape the engine only tolerates',
37	  why: 'every legacy shape here is read through a tolerance that comes out a week after this advisory ships (#1638) — the canon cannot see which repos still carry the old shape, so a repo that does not act inside that window loses its mount rather than holding the removal up',
38	
39	  run(ctx) {
40	    const names = Array.isArray(settingsNames.SETTINGS_FILES) ? settingsNames.SETTINGS_FILES : [];
41	    const file = names.find((n) => ctx.files.includes(n));
42	    if (!file) return [];                                  // not a member — inert
43	
44	    let raw;
45	    try { raw = JSON.parse(ctx.read(file) ?? ''); } catch { return []; }
46	    if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return [];
47	
48	    const out = [];
49	    const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
50	
51	    if (typeof settingsNames.LEGACY_SETTINGS_FILE === 'string' && file === settingsNames.LEGACY_SETTINGS_FILE) {
52	      flag(`the declaration is still named ${settingsNames.LEGACY_SETTINGS_FILE}`,
53	        `rename it to ${settingsNames.SETTINGS_FILE} — the file gained parameters, waits and schedules that are not checks, and the old name is read only until every member is off it`);
54	    }
55	
56	    for (const key of Array.isArray(repoContext.LEGACY_CONFIG_KEYS) ? repoContext.LEGACY_CONFIG_KEYS : []) {
57	      if (raw[key] !== undefined) {
58	        flag(`the declaration carries the retired top-level "${key}" block`,
59	          'move its contents to their current homes — a pack\'s parameters to that pack\'s entry `config`, the stamp to `engineVersion` plus each entry\'s own `version`, delivery to `requirePrReview` — and delete the block');
60	      }
61	    }
62	
63	    if (raw.packConfig !== undefined) {
64	      flag('the declaration carries a top-level "packConfig" map',
65	        'move each pack\'s parameters onto that pack\'s own entry in `packs` as `config`, where a version cannot outlive the pack it prices, and delete the top-level map');
66	    }
67	
68	    const endpointsKey = repoContext.LEGACY_ENDPOINTS_KEY;
69	    if (typeof endpointsKey === 'string' && raw.taskScheduler?.[endpointsKey] !== undefined) {
70	      flag(`taskScheduler.${endpointsKey} is the retired spelling`,
71	        `rename it to taskScheduler.${repoContext.ENDPOINTS_KEY ?? 'agenticTaskInvocationEndpoints'} — these are the routine URLs a task's agentic phase is invoked through, and the bare name said nothing about which endpoints it meant`);
72	    }
73	
74	    // Only where the block actually holds a stamp: its other contents are the
75	    // config-key finding above, and two findings for one block would read as two
76	    // separate edits.
77	    const stamp = typeof installedVersions.LEGACY_STAMP_KEY === 'string' ? raw[installedVersions.LEGACY_STAMP_KEY] : undefined;
78	    if (stamp?.engineVersion !== undefined || stamp?.packVersions !== undefined) {
79	      flag(`the version stamp still lives in the "${installedVersions.LEGACY_STAMP_KEY}" block`,
80	        'let the converge restamp it — the engine version belongs at the top level as `engineVersion` and each pack\'s version on its own `packs` entry; if the converge has run and the block is still here, the record that reshapes it has not reached this mount');
81	    }
82	
83	    const entries = Array.isArray(raw.packs) ? raw.packs : [];
84	    const idOf = (e) => (typeof e === 'string' ? e : (e && typeof e === 'object' && typeof e.id === 'string' ? e.id : null));
85	    const renames = renamedPacks.RENAMED_PACKS ?? {};
86	    const localPrefix = packRegistry.LEGACY_LOCAL_DECL_PREFIX;
87	
88	    for (const entry of entries) {
89	      const id = idOf(entry);
90	      if (id === null) continue;
91	      if (typeof localPrefix === 'string' && id.startsWith(localPrefix)) {
92	        flag(`the pack entry "${id}" uses the retired declaration prefix "${localPrefix}"`,
93	          `declare it as "${id.replace(localPrefix, packRegistry.LOCAL_DECL_PREFIX ?? 'local/')}" — this repo's own packs are discovered from .claudinite/local/packs/ and the old prefix resolves only while the tolerance stands`);
94	      }
95	      if (Object.hasOwn(renames, id)) {
96	        flag(`the pack entry "${id}" names a pack that has been renamed or absorbed`,
97	          `declare "${renames[id]}" instead — an id is matched literally when packs activate, so on the day the rename map comes out this entry activates nothing at all, the self-refresh included`);
98	      }
