// converging one mount from ever fighting over a file.
export const isPackFile = (rel, id) => rel.startsWith(`packs/${id}/`);

// The mount directories a pack has been vendored under BEFORE — every spelling that
// resolves to this id today (renamed-packs.mjs). A rename moves a pack's canon
// directory, and the vendor step below replaces a tree per id: the old directory
// matches no id any more, so without this it would sit in the mount forever holding a
// complete, loadable copy of the pack. That copy is not inert — `discoverPacks`
// canonicalizes a mounted pack's own id, so the stale tree announces the SAME id as
// the live one and the member runs the pack twice, one of them frozen at whatever it
// was renamed from. Swept here rather than by a migration record so the cleanup is a
// property of renaming, not something each rename has to remember.
export const legacySpellingsOf = (id) =>
  Object.entries(RENAMED_PACKS).filter(([, to]) => to === id).map(([from]) => from);

// The records this repo still needs for one pack, oldest first — the same predicate
// the engine flow ranges over, with that pack's number instead of the engine's.
=== dormancy
//
// Import-light and free of `node:` on purpose: the dashboard page reads this in the
// browser through the pack's published shared-code/, and a `node:` import anywhere in
// that graph blocks the page's first module load.
import { RENAMED_PACKS } from '../../engine/pack_loader/renamed-packs.mjs';

// Whose parameter this is. Exported because a reader that has to name the pack to find
// its config should name it from here rather than spell the id a second time.
export const TASKS_PACK_ID = 'claudinite-tasks';

// A declared id as it resolves today. A member's declaration can carry a spelling from
// before a rename, and the config of a pack a member writes into its own repo must keep
// resolving under every spelling it was ever written under.
const resolves = (id) => typeof id === 'string' && (RENAMED_PACKS[id] ?? id) === TASKS_PACK_ID;

// This pack's parameters, from whichever shape the caller holds.
//
=== pack-registry 370-395
// `{ id, config?, rules?, accept?, via? }` carrying that pack's own settings
// (see engine/checks/README.md). This is the one id-extractor every reader shares, so
// raw-JSON consumers (the SessionStart hooks, the fleet signal probe) and the
// engine agree on both shapes — and on both declaration forms: it returns the
// BARE pack id, stripping a `local_packs/` namespace where one is declared.
// Returns undefined for a malformed entry.
// A declaration written before a canon pack was renamed resolves to the pack's
// CURRENT id here (renamed-packs.mjs), so activation, config lookup and the vendor
// set all agree on one spelling no matter which one the member wrote. A LOCAL pack
// is exempt: its namespace belongs to the repo, so `local/core` stays `core`.
// A local pack declared BARE cannot be told apart from a canon one at this seam and
// is canonicalized with the rest — which is harmless while the shadow guard in
// discoverPacks keeps a local id from claiming a canon one.
export const packEntryId = (entry) => {
  const raw = typeof entry === 'string'
    ? entry
    : entry !== null && typeof entry === 'object' && typeof entry.id === 'string'
      ? entry.id
      : undefined;
  if (raw === undefined) return undefined;
  const bare = stripLocalPrefix(raw);
  return bare === raw ? canonicalPackId(bare) : bare;
};

// No pack is active by default. Activation is exactly the project's declaration
// in .claudinite-settings.json (bootstrap's --init seeds the default-on packs).

